    "lifeStory": "慧可大师，俗姓姬，名神光，虎牢（今河南荥阳）人。少为儒生，博涉诗书，尤精玄理，后出家遍学大小乘教义，仍叹曰：“孔老之教，礼术风规；庄易之书，未尽妙理。近闻达摩大士住止少林，至人不遥，当造玄境。”遂至少林参礼达摩。\n\n其年十二月九日夜，神光立雪断臂，求得“安心法门”——觅心了不可得，当下契悟。随侍达摩六年，精研一乘之旨。达摩付法时授《楞伽经》四卷，嘱曰：“吾观汉地，惟有此经，仁者依行，自得度世。”达摩西归后，慧可于黄河沿岸韬光养晦，或入酒肆，或过屠门，或习街谈，或随厮役，人问之，答曰：“我自调心，何关汝事？”后于邺都（今河南安阳）大弘禅法，却遭讲席法师嫉恨，几遭毒手。大师安然顺受，曰：“我宿负汝债，今当偿还。”开皇十三年（593年）于洛州安然而化，世寿一百零七岁。其法脉传三祖僧璨，所传“是心是佛，是心是法”之旨，为后世禅门安心之祖源。",
