    "lifeStory": "惠能大师，俗姓卢，岭南新州（今广东新兴）人。三岁丧父，与母孤苦相依，樵采供养。一日负柴入市，闻客诵《金刚经》至“应无所住而生其心”，言下心开，遂问经从何来，客言黄梅五祖弘忍大师处。惠能安顿老母，跋涉三十余日至黄梅，弘忍问：“汝何方人？欲求何物？”答曰：“弟子是岭南新州百姓，唯求作佛，不求余物。”弘忍曰：“汝是岭南人，又是獦獠，若为堪作佛？”惠能曰：“人虽有南北，佛性本无南北，獦獠身与和尚不同，佛性有何差别？”弘忍知其根器，令入碓坊踏碓。\n\n八月余后，弘忍密召入室，为说《金刚经》，至“应无所住而生其心”，惠能言下大悟，连呼五个“何期”：“何期自性本自清净！何期自性本不生灭！何期自性本自具足！何期自性本无动摇！何期自性能生万法！”遂受衣钵，为第六祖，时年二十四。南归隐遁四会猎人队十五年，后于广州法性寺值印宗法师讲《涅槃经》，闻二僧争论风动幡动，惠能进曰：“不是风动，不是幡动，仁者心动。”一语惊四座，印宗为之剃度，请说东山法门。次年还曹溪宝林寺，大阐顿悟宗旨，学徒万余，嗣法弟子四十三人，著《六祖法宝坛经》——中国祖师著作唯一称“经”者。先天二年（713年）示寂于新州国恩寺，肉身至今供奉于南华寺。",
