    "lifeStory": "神会大师，襄阳人，俗姓高。年十三，自玉泉寺来参六祖惠能。六祖问：“知识远来艰辛，还将得本来否？若有本则合识主，试说看。”神会答：“以无住为本，见即是主。”六祖杖之。神会再问：“和尚坐禅，还见不见？”六祖以拄杖打三下，反问：“吾打汝痛不痛？”神会答：“亦痛亦不痛。”六祖曰：“吾亦见亦不见。”神会再问，六祖曰：“吾之所见，常见自心过愆，不见他人是非好恶，是以亦见亦不见。汝言亦痛亦不痛如何？汝若不痛，同其木石；若痛，则同凡夫，即起恚恨。汝向前见不见是二边，痛不痛是生灭。汝自性且不见，敢尔戏论！”神会汗流浃背，礼拜悔谢，自此服勤左右，得受心印。\n\n开元二十年（732年），神会于滑台（今河南滑县）大云寺设无遮大会，与北宗崇远法师公开论辩，力斥神秀一系“师承是傍，法门是渐”，确立惠能南宗为达摩正统、《金刚经》为传法心印。安史之乱中，神会以八旬之躯主持戒坛度僧，所获香油钱资助军需，于两京收复有功，肃宗诏入内供养。自此南宗顿教风行天下，北宗渐门遂绝。上元元年（758年）示寂，世寿七十五，德宗贞元十二年（796年）敕定其为禅宗第七祖。所著《显宗记》以“无念为宗，无作为本，真空为体，妙有为用”总持南宗宗旨。",
    "teachings": "神会之学，单刀直入，直指人心：道本圆成，不用更加修证；佛性虚灵，岂借有漏之功。他特别拈出“知之一字，众妙之门”的灵知之旨（宗密述其宗义），谓空寂之心，灵知不昧，即此空寂之知，是汝真性。又辨顿渐：“理即顿悟，乘悟并销；事非顿除，因次第尽。”为后世顿悟渐修说之先声。",
    "quotes": [
      "无念为宗，无作为本。真空为体，妙有为用。 —《显宗记》",
      "迷时人逐法，悟时法由人。 —《显宗记》",
      "理即顿悟，乘悟并销；事非顿除，因次第尽。 —《显宗记》",
      "以无住为本，见即是主。 —答六祖问本来"
    ],
