    "lifeStory": "文殊师利（Mañjuśrī），意译“妙吉祥”，大乘般若智慧之化身，过去七佛之师。在《圆觉经》首章代众请问“如来本起清净因地法行”，引出全经总纲；在《维摩诘经》中奉命率诸菩萨声闻前往问疾，与维摩诘往复酬唱，至入不二法门处亲赞“默然无言”为究竟；在《楞严经》中受佛敕令拣选二十五圆通，判观世音耳根圆通为娑婆当机第一。禅宗尊其为“大智”，凡般若法筵，必以文殊为当机唱导之首。",
