    "lifeStory": "玄奘，洛州缑氏（今河南偃师）人，俗姓陈。十三岁出家，博通经论，然感各宗义理纷歧，遂决意西行求法。贞观三年（629年）孤身涉流沙、越葱岭，历尽艰辛，至那烂陀寺从戒贤论师学《瑜伽师地论》及唯识法相之教。游学五印度十七年，辩才无碍，名震五印。归国后于长安弘福寺、大慈恩寺设译场，译出《大般若经》《瑜伽师地论》《成唯识论》等七十五部一千三百余卷。其所传唯识法相之学，后由弟子窥基开创法相唯识宗。禅宗虽以\u201c教外别传\u201d自居，然《楞严经》一经，自唐宋以来为禅宗所重，其\u201c七处征心\u201d\u201c八还辨见\u201d之教，皆与禅宗直指人心之旨相通。",
