    "lifeStory": "僧肇，京兆长安（今陕西西安）人。家贫，以佣书为业，遂博览经史，尤好老庄。后读旧译《维摩诘经》，欢喜顶受，始悟老庄未尽妙理，遂出家。闻鸠摩罗什至姑臧，往从之，为罗什四大弟子之首。随罗什入长安，助译经论。著《肇论》四篇——《物不迁论》《不真空论》《般若无知论》《涅槃无名论》——以中观般若之理，融通老庄玄学，阐明\u201c即动而静\u201d\u201c即静而动\u201d之旨，为中国佛教般若学之巅峰之作。其\u201c天地与我同根，万物与我一体\u201d之语，与禅宗\u201c万法归一\u201d之旨相通。",
    "teachings": "僧肇之学，以中观般若为宗：物不迁者，即动而静；不真空者，即有而空；般若无知者，即知而无知；涅槃无名者，即名而无名。四论皆以\u201c即\u201d字为眼——即俗而真，即事而理，不离世间而证涅槃。此与禅宗\u201c不离世间觉\u201d之旨一脉相通。",
    "quotes": [
      "旋岚偃岳而常静，江河竞注而不流。 —《物不迁论》",
      "天地与我同根，万物与我一体。 —《涅槃无名论》",
      "般若无知，无所不知。 —《般若无知论》"
    ],
