    "lifeStory": "宣鉴禅师，剑南西川（今四川成都）人，俗姓周。少出家，精研律藏，常讲《金刚经》，时人谓之\u201c周金刚\u201d。后闻南方禅宗盛倡\u201c直指人心，见性成佛\u201d，师不平，携自著《金刚经》疏钞南行，欲破禅宗之学。至澧阳路上遇一卖饼婆子，婆子问：\u201c《金刚经》云过去心不可得，现在心不可得，未来心不可得，上座要点哪个心？\u201d师无语。婆子指示往参龙潭崇信，师于龙潭座下悟道，遂将疏钞一把火烧却。后住德山（今湖南常德），以棒打接人，凡有学人问话，师便打，所谓\u201c道得也三十棒，道不得也三十棒\u201d，世称\u201c德山棒\u201d，与临济之\u201c喝\u201d并称。",
    "teachings": "德山宗风以\u201c棒\u201d为施设：不问道理，不论是非，开口便打，逼学人于思量不及处亲见本来。其教贵在\u201c截断\u201d——以一棒截断学人意识流，令其于言语道断处瞥见自性。此风下启雪峰，雪峰下出云门、法眼，影响深远。",
