    "lifeStory": "龙树，梵语 Nāgārjuna，南印度人。出家后广学三藏，后于龙宫得《华严经》，大弘大乘般若中观之教。著《中论》《大智度论》《十二门论》等，以\u201c因缘所生法，我说即是空\u201d为根本教义，立\u201c八不中道\u201d——不生不灭、不常不断、不一不异、不来不去。龙树为禅宗西天第十四祖，传法于迦那提婆。其般若中观之教，经鸠摩罗什译传中土，直接影响禅宗\u201c直指人心\u201d之教理基础。僧肇之《肇论》即承龙树中观之学而立。",
