    "name": "罗汉桂琛",
    "title": "法眼文益之师 / 玄沙师备法嗣",
    "era": "五代 (867-928)",
    "lifeStory": "桂琛禅师，常山（今浙江常山）人，俗姓李。初学唯识，后参玄沙师备，于师备座下开悟。师住漳州罗汉院，以\u201c一切现成\u201d接引法眼文益：文益参师，遇雪阻留，师问：\u201c作什么行脚？\u201d文益曰：\u201c寻访知识。\u201d师曰：\u201c行脚人三句中须辨，两句中须明，一句中须具。只如一句中，作么生辨？\u201d文益无语。师曰：\u201c不知若何，且坐吃茶。\u201d后文益辞行，师送至门外，曰：\u201c上座寻常说\u2018三界唯心，万法唯识\u2019，且道脚下这块石头，是在心内还是在心外？\u201d文益曰：\u201c在心内。\u201d师曰：\u201c行脚人著甚来由，安一块石头在心头？\u201d文益大窘，乃留止月余，终于言下大悟\u201c一切现成\u201d之旨。",
    "teachings": "罗汉宗风以\u201c一切现成\u201d为纲要：道不假外求，法本自具足。脚下石头不在心外，然亦不可安在心头——既不可拨无，亦不可执着。其教贵在\u201c遣执\u201d，层层剥去学人知见，令其于无措手足处亲见本来。",
    "quotes": [
      "行脚人著甚来由，安一块石头在心头？ —接引法眼",
      "不知若何，且坐吃茶。"
    ],
