    "lifeStory": "法融禅师，润州延陵（今江苏丹阳）人，俗姓韦。十九岁出家，博通经论，后于牛头山（今江苏南京）幽栖寺北岩结庵修行，世称\u201c牛头法融\u201d。四祖道信访之，问：\u201c百千法门，同归方寸，河沙妙德，总在心源。汝今何不观心？\u201d师曰：\u201c观心何法？\u201d道信为之广说\u201c绝观\u201d之旨——无心可观，无境可遣，方为真观。师大悟，遂承四祖法脉，开牛头一宗。著《绝观论》《心铭》，以\u201c无心\u201d为宗，明\u201c一切诸法，本来寂灭\u201d之旨。牛头宗传六世，至牛头慧忠，融通般若与禅观，为早期禅宗重要流派。",
