    "era": "唐代 (772-841)",
    "lifeStory": "李翱，字习之，陇西（今甘肃陇西）人，唐代著名儒者、文学家，韩愈之门人。任朗州刺史时，闻药山惟俨禅师之名，往参之。师不顾，李翱忿曰：\u201c见面不如闻名。\u201d师呼曰：\u201c太守何得贵耳贱目？\u201d李翱拱谢，问曰：\u201c如何是道？\u201d师以手上下指，曰：\u201c会么？\u201d翱曰：\u201c不会。\u201d师曰：\u201c云在天，水在瓶。\u201d翱大悟，欣然作偈：\u201c练得身形似鹤形，千株松下两函经。我来问道无余说，云在青天水在瓶。\u201d李翱以儒入禅，著《复性书》三篇，融通儒佛，以\u201c诚明\u201d会禅宗\u201c自性\u201d，开宋明理学\u201c援禅入儒\u201d之先河。",
