    "lifeStory": "袾宏，字佛慧，号莲池，杭州仁和（今浙江杭州）人，俗姓沈。三十二岁出家，后住杭州云栖寺，大弘禅净双修之教，世称\u201c云栖大师\u201d，与紫柏真可、憨山德清、蕅益智旭并称明代四大高僧。师虽承禅宗法脉，然融通禅、净、教、律各宗，以\u201c一心\u201d统摄万法。著《禅关策进》一卷，集古德参禅警策之语，为后世禅修之入门指南。又倡\u201c念佛即是参禅\u201d，谓\u201c参禅念佛等法门，毕竟是生灭心行\u201d，以念佛摄心，以参禅明理，理事圆融，开明清禅净合流之风气。",
