    "summary": "参话头，大慧宗杲所倡看话禅之具体修法。以一则公案之\u201c话头\u201d为所缘——如\u201c无\u201d字、\u201c父母未生前本来面目\u201d、\u201c念佛是谁\u201d、\u201c万法归一，一归何处\u201d——将一切思量分别扫除，唯以疑情穷追不舍。话头者，话之头——即一句话未生起之前的状态。参话头非参话尾（分析理解公案），乃参话头——于一念未生处穷追到底。疑情如石头堵在胸口，吐不出、咽不下，至山穷水尽时，疑情忽然爆破，豁然大悟。",
