    "answer": "诸佛妙理，非关文字。",
    "context": "六祖惠能隐居韶州曹溪时，有一尼名无尽藏，常诵《大般涅槃经》。六祖听闻片刻，即知经中妙理，遂为解说。尼执卷问字，六祖曰：“字即不识，义即请问。”尼曰：“字尚不识，焉能解义？”六祖曰：“诸佛妙理，非关文字。”尼大为惊异，遍告乡里，同来瞻礼。",
