    "interpretation": "赵州之\u201c洗钵去\u201d，示禅宗\u201c平常心是道\u201d之旨。吃粥、洗钵——最平常之日用事，然于此平常中，即具大道。僧人\u201c乍入丛林\u201d，心存\u201c求道\u201d之念——以为道在别处、在玄妙处。赵州以\u201c吃粥了也未\u201d\u201c洗钵去\u201d截断其求心：道不在别处，即此洗钵之当下便是。僧于言下大悟——悟者非悟别事，乃悟道在日用，不离平常。",
