    "question": "如何是佛？",
    "answer": "即心是佛。",
    "context": "僧问马祖：\u201c如何是佛？\u201d师曰：\u201c即心是佛。\u201d僧曰：\u201c如何是即心是佛？\u201d师曰：\u201c汝唤什么作心？汝唤什么作佛？\u201d",
    "interpretation": "马祖反问\u201c汝唤什么作心？汝唤什么作佛？\u201d——截断学人对\u201c即心是佛\u201d之理解。学人闻\u201c即心是佛\u201d，必以意识分别解会：\u201c我的心就是佛\u201d——此解已是妄心，非即心即佛之本意。马祖反问，令其于思量不及处亲见——心非心，佛非佛，即心即佛非言说之事，乃亲证之境。",
