    "question": "如何是诸佛出身处？",
    "answer": "薰风自南来，殿阁生微凉。",
    "context": "僧问五祖法演禅师：\u201c如何是诸佛出身处？\u201d师曰：\u201c薰风自南来，殿阁生微凉。\u201d",
    "interpretation": "法演以诗句答\u201c诸佛出身处\u201d——薰风南来，殿阁生凉，自然之景，不假造作。诸佛出身处不在别处——即此自然之日用。薰风自南来，非为殿阁而风；殿阁生微凉，非为薰风而凉——因缘时至，自然现前。诸佛之出世亦如是：非造作而得，乃因缘时至，自然显现。",
