    "question": "如何是和尚家风？",
    "answer": "不使学者断肠。",
    "context": "僧问法眼文益禅师：\u201c如何是和尚家风？\u201d师曰：\u201c不使学者断肠。\u201d",
    "interpretation": "法眼文益之\u201c不使学者断肠\u201d——法眼宗风以\u201c温和\u201d著称，不似临济之棒喝、德山之峻烈。法眼家风，因材施教，循循善诱，不令学人因参究过度而\u201c断肠\u201d——身心俱疲。此非法眼宗不峻烈，乃法眼宗之\u201c峻烈\u201d在温和中——如春风化雨，润物无声，然其截断学人执着之力，不在棒喝之下。",
