    "question": "如何是西来意？",
    "answer": "适来记得，今却忘却。",
    "context": "僧问赵州从谂禅师：\u201c如何是祖师西来意？\u201d师曰：\u201c适来记得，今却忘却。\u201d",
    "interpretation": "赵州之\u201c适来记得，今却忘却\u201d——以幽默之语截断学人之追问。学人执意要知\u201c西来意\u201d，赵州以\u201c记得又忘却\u201d答之——既已忘却，何须再问？赵州之意：西来意不在记忆中、不在思量中——越想越远，越问越迷。不如当下放下一切思量，即此\u201c忘却\u201d处，便是西来意。",
