    "interpretation": "赵州之\u201c久响不如初闻\u201d——久闻其名，不如初闻之一刻。学人久参\u201c西来意\u201d，已成老问题——越参越远，越问越迷。赵州之意：不如回到\u201c初闻\u201d之那一刻——初闻时心无成见、无思量、无分别——即此初闻之清净心，便是祖师西来意。如人初闻一声，心无分别——即此无分别之心，便是道。",
