    "question": "如何是道？",
    "answer": "好灯。",
    "context": "僧问俱胝和尚：\u201c如何是道？\u201d师竖一指。僧又问：\u201c如何是道？\u201d师又竖一指。凡有参学僧问，师唯竖一指。",
    "interpretation": "俱胝竖一指——此为禅宗最简洁之开示。一指者，非一指——乃万法归一之一。凡有问，唯竖一指——不容拟议，截断一切思量。学人若于一指上思量\u201c这是什么意思\u201d，已是错会；若能于一指下转身，即见万法归一、一即万法。然俱胝临终曰：\u201c吾得天龙一指禅，一生用不尽。\u201d——可见一指非形式，乃悟后之妙用。",
