    "interpretation": "石巩以张弓射箭接引学人——此为禅宗最独特之机锋。张弓者，非真射箭——乃以弓箭截断学人之思量。三平拊掌——以拊掌答张弓：不惧弓箭，以平常心对之。石巩叹\u201c只射得半个圣人\u201d——三平虽不惧，然仅\u201c拊掌\u201d而已，尚未大悟——故为\u201c半个圣人\u201d。石巩之弓箭，非射身——乃射心：射断学人之妄想执着。",
