    "answer": "庭前柏树子。",
    "context": "僧问赵州从谂禅师：\u201c如何是祖师西来意？\u201d师曰：\u201c庭前柏树子。\u201d僧曰：\u201c和尚莫将境示人。\u201d师曰：\u201c我不将境示人。\u201d僧曰：\u201c如何是祖师西来意？\u201d师曰：\u201c庭前柏树子。\u201d",
    "interpretation": "赵州之\u201c庭前柏树子\u201d——此为禅宗最著名公案之一。学人问西来意，赵州以眼前柏树答之——祖师西来意不在玄妙处，即此庭前柏树。僧人以为赵州\u201c将境示人\u201d——以境物答佛法，已落境执。赵州答\u201c我不将境示人\u201d——柏树非境，乃自性之显现。僧人再问，赵州再答\u201c庭前柏树子\u201d——不换答案，不容拟议。即此柏树，当下一念不生时，即是祖师西来意。",
    "master": "赵州从谂",
    "source": "赵州语录 / 无门关第三十七则",
    "relatedConcepts": ["koan", "ordinary-mind", "direct-pointing"],
