    "id": "qa-95",
    "question": "黄檗三顿棒",
    "answer": "黄檗佛法无多子。",
    "context": "临济义玄禅师初在黄檗会下，三次问佛法，三次被打。后参大愚，大愚问：\u201c什么处来？\u201d临济曰：\u201c黄檗来。\u201d大愚曰：\u201c黄檗有何言句？\u201d临济曰：\u201c某甲三度问佛法，三度被打，不知某甲有过无过。\u201d大愚曰：\u201c黄檗恁么老婆心切，为汝得彻困，更来这里问有过无过。\u201d临济于言下大悟，曰：\u201c原来黄檗佛法无多子。\u201d",
    "interpretation": "临济三度问佛法，三度被黄檗打——黄檗不以言语答，以棒打截断临济之思量。临济当时不悟，疑自己有过无过。大愚点破：\u201c黄檗老婆心切\u201d——黄檗以棒打为慈悲，老婆心切为汝得彻困。临济于言下大悟——悟得黄檗棒打之旨：佛法不在言语中，棒打即是直指。\u201c原来黄檗佛法无多子\u201d——黄檗佛法没有多少，即此棒打便是。此为临济悟道之关键公案。",
