    "context": "僧问大阳警玄禅师：\u201c如何是祖师西来意？\u201d师曰：\u201c风吹碧海。\u201d",
    "interpretation": "大阳之\u201c风吹碧海\u201d——风吹碧海，波涛自然生起——不假造作，因缘和合。祖师西来意亦如是——因缘和合，自然现前。如风吹海——风非造波，海非受波，因缘和合而波自生。悟道亦如是——非造作，非受动，因缘和合而自悟。",
    "master": "大阳警玄",
    "source": "五灯会元",
