    "interpretation": "马祖之\u201c平常心是道\u201d——此为禅宗最根本之教义之一。平常心者——无造作（不假功用）、无是非（不分别善恶）、无取舍（不执着好恶）、无断常（不落断常二边）、无凡无圣（不分别凡圣）。即此平常心，便是道。道不在玄妙处——即此最平常之无造作、无分别之心。如赵州\u201c吃茶去\u201d、大珠\u201c饥来吃饭困来即眠\u201d——皆平常心是道之展开。",
